{
  "case_id": "xsu_sg_012_current_specialist_statement",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "not_met", "reason": "Svaret mangler den centrale begrænsning 'i særlige tilfælde'. Det angiver generelle udløsere (kompleks sag, tvivl om handicappets art/omfang, behov for at opdatere oplysninger), som ikke står i kilden. Samtykkeprocedure, 'redegørelsen skal typisk omfatte' og behandlingsmuligheder/-resultater er ikke støttet. De tre kildeudløsere nævnes ikke."},
    "c02_required_elements_complete": {"label": "not_met", "reason": "Ingen af de tre konkrete situationer er med tydeligt: journaloplysninger der indikerer funktionstab uden beskrivelse af funktionsniveau, forlængelse af tidsbegrænset tillæg med forældet dokumentation, og påbegyndt behandlingsforløb med begrænsede lægeoplysninger. 'Opdatere eller verificere tidligere oplysninger' rammer kun løst forlængelsessituationen. 'Særlige tilfælde' er ikke bevaret."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret forsøger at besvare spørgsmålet om, hvornår UDK kan indhente en aktuel redegørelse, og er ikke irrelevant, selvom indholdet er upræcist."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen kilde, hverken lov, bekendtgørelse eller vejledning."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så gyldighed kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så støtte kan ikke vurderes."},
    "c07_no_unsupported_legal_additions": {"label": "not_met", "reason": "Svaret tilføjer ikke-understøttede regler: kompleks eller usædvanlig sag som udløser, samtykkeprocedure, indholdskrav til redegørelsen (behandlingsmuligheder og -resultater, evne til at deltage i undervisning) og at UDK tager stilling til retten 'i givet fald i hvilket omfang'. Intet af dette findes i kilderne."},
    "c08_qualifications_and_exceptions": {"label": "not_met", "reason": "Det krævede forbehold 'kan i særlige tilfælde' mangler; i stedet er der en bred 'hvis der er behov for yderligere oplysninger'. Svaret nævner heller ikke, at forældet dokumentation er en typisk situation ved forlængelse. Det nævner ikke, at fremmøde er udgangspunkt."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Svaret er internt sammenhængende: behov for oplysninger, udløsere, proces og afgørelse. Der er ingen indbyrdes modsigelser, selvom præmisserne er juridisk forkerte."},
    "c10_legal_modality_precision": {"label": "not_met", "reason": "Den snævre adgang 'kan i særlige tilfælde' er gjort til en bred adgang ved generelt behov for oplysninger. Redegørelsens indhold og samtykkeproceduren er beskrevet som typisk eller fast praksis uden støtte i kilden. Modaliteten svarer ikke til kilden."}
  },
  "xhaile_coverage": {
    "A69": {"label": "no", "reason": "Svaret nævner ikke journaloplysninger, der indikerer funktionstab, men hvor funktionsniveau og påvirkning ikke er beskrevet. 'Tvivl om handicappets art og omfang' er en anden og bredere formulering."},
    "A70": {"label": "partial", "reason": "'Behov for at opdatere eller verificere tidligere indhentede oplysninger' berører løst forældede oplysninger, men svaret nævner hverken forlængelse af et tidsbegrænset tillæg eller forældet dokumentation som typisk situation."},
    "A71": {"label": "no", "reason": "Svaret nævner ikke påbegyndt behandlingsforløb ved ansøgning kombineret med begrænsede lægelige oplysninger."}
  },
  "overall_notes": "Svaret er generisk og mangler både de tre specifikke situationer og forbeholdet 'i særlige tilfælde'. Det tilføjer ustøttede udløsere og proceduredetaljer og angiver ingen kilde. Derfor er C04 not_met, mens C05 og C06 er not_assessable."
}

